        #[inline]
        fn error_action(&self, state: i8) -> i8 {
            __action(state, 59 - 1)
        }

        #[inline]
        fn eof_action(&self, state: i8) -> i8 {
            __EOF_ACTION[state as usize]
        }

        #[inline]
